{"content": "17|/// GPU weight cache: maps (ptr, len) → cached device buffer.
18|/// Avoids redundant H2D transfers of the same weight buffer across decode steps.
19|struct WeightCache {
20|    buffers: HashMap<CacheKey, cudarc::driver::CudaSlice<half::f16>>,
21|}
22|
23|#[derive(Debug)]
24|struct CacheKey {
25|    ptr: usize,
26|    len: usize,
27|}
28|
29|impl Hash for CacheKey {
30|    fn hash<H: Hasher>(&self, state: &mut H) {
31|        self.ptr.hash(state);
32|        self.len.hash(state);
33|    }
34|}
35|
36|impl PartialEq for CacheKey {
37|    fn eq(&self, other: &Self) -> bool {
38|        self.ptr == other.ptr && self.len == other.len
39|    }
40|}
41|
42|impl Eq for CacheKey {}
43|
44|static WEIGHT_CACHE: OnceLock<Mutex<WeightCache>> = OnceLock::new();
45|
46|fn weight_cache() -> &'static Mutex<WeightCache> {
47|    WEIGHT_CACHE.get_or_init(|| Mutex::new(WeightCache { buffers: HashMap::new() }))
48|}
49|
50|/// Get or upload cached GPU buffer for a weight slice.
51|fn get_or_upload_weights(weights: &[half::f16]) -> Result<cudarc::driver::CudaSlice<half::f16>, String> {
52|    let key = CacheKey { ptr: weights.as_ptr() as usize, len: weights.len() };
53|    let cache = weight_cache();
54|    let mut guard = cache.lock().unwrap();
55|
56|    if let Some(buf) = guard.buffers.get(&key).cloned() {
57|        return Ok(buf);
58|    }
59|
60|    // Not cached — upload to GPU
61|    drop(guard);
62|    let stream = get_stream();
63|    let mut w_dev = unsafe { stream.alloc(weights.len()) }.map_err(|e| format!("cudaMalloc W failed: {:?}", e))?;
64|    stream.memcpy_htod(weights, &mut w_dev).map_err(|e| format!("cudaMemcpy H2D W failed: {:?}", e))?;
65|
66|    // Insert into cache
67|    let mut guard = cache.lock().unwrap();
68|    guard.buffers.insert(key, w_dev.clone());
69|    Ok(w_dev)
70|}
